/**
 * Global Step 3 — Preview.
 *
 * Split view: the finalized media on the left, a brand-consistent Instagram
 * caption on the right. The caption is generated by RAG over historical
 * @42abudhabi captions (backend embeds the topic, retrieves nearest posts, and
 * prompts an LLM). The user can edit it freely before continuing.
 */
import { useEffect, useRef, useState } from "react";

import { api } from "../../../lib/api";
import { useToast } from "../../ToastProvider";
import { roadmapApi, type CaptionResponse } from "./api";
import { CarouselPicker } from "./CarouselPicker";
import type { CarouselSlide, FinalizedAsset } from "./types";

export function PreviewStep({
  asset,
  caption,
  onCaptionChange,
  onBack,
  onConfirm,
}: {
  asset: FinalizedAsset;
  /** Caption draft is owned by the roadmap so it SURVIVES leaving and returning
   *  to Finalization (no auto-regenerate, no lost text). */
  caption: string;
  onCaptionChange: (caption: string) => void;
  onBack: () => void;
  onConfirm: (
    caption: string,
    carouselItems?: CarouselSlide[],
    thumbOffsetMs?: number,
  ) => void;
}) {
  const [refs, setRefs] = useState<CaptionResponse["references"]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const toast = useToast();

  // Reel cover frame — single video posts only. The slider seeks the <video>
  // so the chosen frame previews live; we send its offset (ms) as thumb_offset.
  const videoRef = useRef<HTMLVideoElement>(null);
  const [videoDuration, setVideoDuration] = useState(0);
  // Seed from the asset so returning to Finalization keeps the chosen cover.
  const [thumbSec, setThumbSec] = useState((asset.thumbOffsetMs ?? 0) / 1000);

  // Slide 1 is always this finished asset; more slides → an Instagram carousel.
  const slide1: CarouselSlide = {
    tool: asset.tool, refId: asset.refId, mediaType: asset.mediaType,
    mediaUrl: asset.mediaUrl, topic: asset.topic,
  };
  const [slides, setSlides] = useState<CarouselSlide[]>(
    asset.carouselItems && asset.carouselItems.length >= 1 ? asset.carouselItems : [slide1],
  );
  const [pickerOpen, setPickerOpen] = useState(false);

  // Video Editor assets render in the BACKGROUND — the user clicked "Finish &
  // continue" and we advanced here immediately. Poll the project's composition
  // status and only reveal the MP4 once it's ready. (Non-VE assets are ready.)
  const isVideoEditor = asset.tool === "video_editor";
  const [compStatus, setCompStatus] = useState<string | null>(isVideoEditor ? null : "ready");
  useEffect(() => {
    if (!isVideoEditor) return;
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout> | null = null;
    const tick = async () => {
      try {
        const p = await api.yasProducer.videoEditor.fetch(asset.refId);
        const st = p.render?.composition_status ?? null;
        if (cancelled) return;
        setCompStatus(st);
        if (st !== "ready" && st !== "failed") timer = setTimeout(tick, 4000);
      } catch {
        if (!cancelled) timer = setTimeout(tick, 4000);
      }
    };
    void tick();
    return () => {
      cancelled = true;
      if (timer) clearTimeout(timer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isVideoEditor, asset.refId]);

  const mediaReady = !isVideoEditor || compStatus === "ready";
  const mediaFailed = isVideoEditor && compStatus === "failed";

  function removeSlide(i: number) {
    if (i === 0) return; // slide 1 is fixed (this asset)
    setSlides((s) => s.filter((_, idx) => idx !== i));
  }
  function move(i: number, dir: -1 | 1) {
    setSlides((s) => {
      const j = i + dir;
      if (i <= 0 || j <= 0 || j >= s.length) return s; // keep slide 1 first
      const next = s.slice();
      [next[i], next[j]] = [next[j], next[i]];
      return next;
    });
  }

  async function generate() {
    setLoading(true);
    setError(null);
    try {
      const r = await roadmapApi.caption({
        tool: asset.tool,
        ref_id: asset.refId,
        topic: asset.topic,
      });
      onCaptionChange(r.caption);
      setRefs(r.references || []);
    } catch (e: any) {
      setError(e?.message || String(e));
    } finally {
      setLoading(false);
    }
  }

  // NO auto-generate — the caption is written only when the user clicks
  // "Generate" (and it persists via the lifted `caption` prop, so revisiting
  // Finalization never regenerates or loses it).

  function continueToCalendar() {
    const text = caption.trim();
    if (!text) {
      toast.error("Caption required", "Write or generate a caption first");
      return;
    }
    const isCarousel = slides.length >= 2;
    // Cover frame applies to single video posts only; send ms when the user
    // scrubbed past the default first frame.
    const thumbOffsetMs =
      !isCarousel && asset.mediaType === "video" && thumbSec > 0
        ? Math.round(thumbSec * 1000)
        : undefined;
    onConfirm(text, isCarousel ? slides : undefined, thumbOffsetMs);
  }

  return (
    <div className="space-y-5">
      <header className="flex items-center gap-3">
        <button onClick={onBack} className="btn btn-ghost text-sm">← Editing</button>
        <h1 className="h1 flex-1">Finalization</h1>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-5 items-start">
        {/* Media */}
        <section className="card p-4">
          <p className="eyebrow mb-2">Final media</p>
          <div
            className="bg-black rounded-lg overflow-hidden flex items-center justify-center"
            style={{ maxHeight: "70vh", minHeight: 200 }}
          >
            {mediaFailed ? (
              <div className="text-center p-6 space-y-2">
                <p className="text-sm text-danger">The export failed to render.</p>
                <button onClick={onBack} className="btn btn-ghost text-xs">
                  ← Back to Editing
                </button>
              </div>
            ) : !mediaReady ? (
              <div className="text-center p-6 space-y-3 text-white/85">
                <span className="inline-block w-6 h-6 rounded-full border-2 border-white/40 border-t-transparent animate-spin" />
                <p className="text-sm">Rendering your video…</p>
                <p className="text-2xs text-white/50">
                  This runs in the background — usually under a minute. Write the caption meanwhile.
                </p>
              </div>
            ) : asset.mediaType === "video" ? (
              <video
                ref={videoRef}
                src={asset.mediaUrl}
                controls
                loop
                onLoadedMetadata={(e) => {
                  setVideoDuration(e.currentTarget.duration || 0);
                  // Show the previously-chosen cover frame on return.
                  if (thumbSec > 0) e.currentTarget.currentTime = thumbSec;
                }}
                className="max-w-full max-h-[70vh] object-contain"
              />
            ) : (
              <img src={asset.mediaUrl} alt={asset.topic} className="max-w-full max-h-[70vh] object-contain" />
            )}
          </div>
          <p className="text-2xs text-muted mt-2 truncate" title={asset.topic}>
            {asset.topic}
          </p>
          {mediaReady && (
            <a
              href={asset.mediaUrl + (asset.mediaUrl.includes("?") ? "&" : "?") + "download=1"}
              download
              className="btn btn-ghost text-xs w-full mt-3"
            >
              ↓ Download {asset.mediaType === "video" ? "video" : "image"}
            </a>
          )}

          {/* Reel cover frame — single video posts only (carousels cover from
              slide 1; images are their own thumbnail). Scrub to pick the frame
              Instagram shows as the cover. */}
          {mediaReady && asset.mediaType === "video" && slides.length < 2 && (
            <div className="mt-4 pt-3 border-t border-border space-y-2">
              <div className="flex items-center justify-between">
                <p className="eyebrow">Instagram cover frame</p>
                <span className="font-mono text-[10.5px] text-muted tabular-nums">
                  {thumbSec.toFixed(1)}s
                </span>
              </div>
              <input
                type="range"
                min={0}
                max={Math.max(0.1, videoDuration)}
                step={0.05}
                value={thumbSec}
                disabled={!videoDuration}
                onChange={(e) => {
                  const t = parseFloat(e.target.value);
                  setThumbSec(t);
                  const v = videoRef.current;
                  if (v) {
                    v.pause();
                    v.currentTime = t;
                  }
                }}
                className="w-full accent-accent disabled:opacity-50"
              />
              <p className="text-[10.5px] text-muted">
                Drag to choose the cover frame shown on the Instagram grid. The
                video above jumps to that frame so you can see it.
              </p>
            </div>
          )}

          {/* Carousel slides — slide 1 is this post; add more to post a carousel. */}
          <div className="mt-4 pt-3 border-t border-border">
            <div className="flex items-center justify-between mb-2">
              <p className="eyebrow">
                {slides.length > 1 ? `Carousel · ${slides.length} slides` : "Carousel"}
              </p>
              {slides.length < 10 && (
                <button onClick={() => setPickerOpen(true)} className="btn btn-ghost text-xs">
                  + Add slide
                </button>
              )}
            </div>
            <div className="flex gap-2 overflow-x-auto pb-1">
              {slides.map((s, i) => (
                <div key={`${s.tool}:${s.refId}`} className="relative shrink-0 w-20">
                  <div className="aspect-square rounded-md overflow-hidden bg-bg-muted border border-border flex items-center justify-center">
                    {i === 0 && isVideoEditor && !mediaReady ? (
                      <span className="w-4 h-4 rounded-full border-2 border-muted border-t-transparent animate-spin" />
                    ) : s.mediaType === "video" ? (
                      <video src={s.mediaUrl} muted playsInline preload="metadata" className="w-full h-full object-cover" />
                    ) : (
                      <img src={s.mediaUrl} alt="" className="w-full h-full object-cover" />
                    )}
                  </div>
                  <span className="absolute top-0.5 left-0.5 font-mono text-[9px] px-1 rounded bg-black/60 text-white">
                    {i + 1}
                  </span>
                  {i > 0 && (
                    <div className="absolute top-0.5 right-0.5 flex gap-0.5">
                      <button onClick={() => move(i, -1)} title="Move earlier" className="w-4 h-4 rounded bg-black/60 text-white text-3xs leading-none">‹</button>
                      <button onClick={() => removeSlide(i)} title="Remove slide" className="w-4 h-4 rounded bg-black/60 text-white text-3xs leading-none">×</button>
                    </div>
                  )}
                </div>
              ))}
            </div>
            {slides.length > 1 ? (
              <p className="text-[10.5px] text-muted mt-1.5">
                Posts as one Instagram carousel · one caption for all slides.
              </p>
            ) : (
              <p className="text-[10.5px] text-muted mt-1.5">
                Add finished posts to turn this into a carousel (up to 10).
              </p>
            )}
          </div>
        </section>

        {/* Caption */}
        <section className="card p-4 space-y-3">
          <div className="flex items-center gap-2">
            <p className="eyebrow">Instagram caption</p>
            <span className="text-3xs text-muted">· RAG over @42abudhabi</span>
            <button
              onClick={generate}
              disabled={loading}
              className={`text-xs ml-auto ${caption.trim() ? "btn btn-ghost" : "btn btn-accent"}`}
              title="Write a brand-voice caption from @42abudhabi history"
            >
              {loading ? "Generating…" : caption.trim() ? "Regenerate" : "✨ Generate"}
            </button>
          </div>

          <textarea
            value={caption}
            onChange={(e) => onCaptionChange(e.target.value)}
            disabled={loading}
            rows={10}
            placeholder={
              loading
                ? "Generating a brand-consistent caption…"
                : "Click ✨ Generate for a brand-voice caption, or write your own…"
            }
            className="textarea w-full font-mono text-[13px] leading-relaxed disabled:opacity-60"
          />

          {error && (
            <p className="text-xs text-danger" role="alert">
              Couldn’t generate ({error}). You can still write one manually.
            </p>
          )}

          {refs.length > 0 && (
            <details className="text-xs text-muted">
              <summary className="cursor-pointer select-none">
                {refs.length} reference post{refs.length === 1 ? "" : "s"} used
              </summary>
              <ul className="mt-2 space-y-1.5">
                {refs.map((r, i) => (
                  <li key={i} className="border-l-2 border-border pl-2">
                    <span className="line-clamp-2">{r.caption}</span>
                    <span className="text-3xs text-muted/70"> · {r.likes} likes</span>
                  </li>
                ))}
              </ul>
            </details>
          )}

          <button
            onClick={continueToCalendar}
            disabled={loading || !caption.trim() || !mediaReady}
            className="btn btn-accent w-full"
            title={!mediaReady ? "Waiting for the export to finish rendering…" : undefined}
          >
            {!mediaReady && !mediaFailed ? "Rendering your video…" : "Continue to Calendar →"}
          </button>
        </section>
      </div>

      {pickerOpen && (
        <CarouselPicker
          existing={slides}
          onAdd={(s) => setSlides((prev) => (prev.length < 10 ? [...prev, s] : prev))}
          onClose={() => setPickerOpen(false)}
        />
      )}
    </div>
  );
}
